from typing import List, Optional

from taf.rfrl.csv4all.resources.test_cases.csv4all_test import test_logger
from taf.rfrl.csv4all.resources.test_cases.module_test import ModuleTest
from taf.rfrl.csv4all.resources.utilities.test_global_constants import KPI_PER_TEST_CASE


class BasebandModuleResetTest(ModuleTest):

    def __init__(self, nodes_details: List[dict], test_nodes_details: List[dict], iterations_per_node: int,
                 report: bool, calculate_kpi: Optional[bool] = True, kpi_targets: Optional[dict] = None,
                 use_dcap: Optional[bool] = False, qc_domain: Optional[str] = None, qc_id: Optional[str] = None,
                 qc_project: Optional[str] = None, customers_list: Optional[list] = None,
                 report_comment: Optional[str] = None, sw_build: Optional[str] = None, topology: Optional[str] = None,
                 stop_test_after_fail: bool = False, l3_call_method: Optional[callable] = None,
                 detailed_console_log: bool = True, collect_passed_logs: int = 0):
        super().__init__(nodes_details, test_nodes_details, iterations_per_node, report,
                         calculate_kpi, kpi_targets, use_dcap, qc_domain, qc_id, qc_project, customers_list,
                         report_comment, sw_build, topology, stop_test_after_fail, l3_call_method, detailed_console_log,
                         collect_passed_logs)
        self.module_type = "baseband"
        self.kpi_to_calculate = KPI_PER_TEST_CASE.get("Baseband Reset")

    def add_allowed_faults_for_each_shared_rmod_on_bbmod(self, active_node, bbmod):
        test_logger(f"Adding allowed alarms: {self.allowed_faults_on_shared_rmods} for shared rmods", "DEBUG")
        if active_node.basebandModules.get(bbmod).get("Radio Modules"):
            for rmod in active_node.basebandModules.get(bbmod).get("Radio Modules"):
                self.add_faults_on_shared_rmod(active_node, rmod, self.allowed_faults_on_shared_rmods)

    def test_operation(self, node):
        bbmod = next(node.modules_for_test)
        self.add_allowed_specific_faults(node, "10", bbmod)
        self.add_allowed_faults_for_each_shared_rmod_on_bbmod(node, bbmod)
        self.add_allowed_dss_faults_as_temporary(node.basebandModules.get(bbmod).get('Mapped Cells'))
        test_logger(f"Starting reset: {bbmod}")
        node.reset_unit(bbmod, reset_type="WARM", timeout=900)
        if self.l3_call_method:
            self.set_l3_all_dependent_cells(node, bbmod)
